<?php require_once 'config.php'; $q=trim($_GET['q']??''); $field=trim($_GET['field']??''); $sql="SELECT s.*,u.name AS owner FROM scholarships s JOIN users u ON s.provider_id=u.id WHERE s.deadline>=CURDATE()"; if($q!==''){ $x=$conn->real_escape_string($q);$sql.=" AND (s.title LIKE '%$x%' OR s.description LIKE '%$x%' OR s.field_of_study LIKE '%$x%')";} if($field!==''){ $x=$conn->real_escape_string($field);$sql.=" AND (s.field_of_study='Any' OR s.field_of_study LIKE '%$x%')";} $sql.=" ORDER BY s.deadline ASC"; $rs=$conn->query($sql); ?>
<!DOCTYPE html><html><head><title>Scholarships</title><?php include 'partials/head.php'; ?></head><body><?php include 'partials/nav.php'; ?><div class="container"><h1 class="page-title">Available Scholarships</h1><form class="searchbar"><input name="q" value="<?=e($q)?>" placeholder="Search title, subject or keyword"><input name="field" value="<?=e($field)?>" placeholder="Field e.g. Computer Science"><button class="btn">Search</button></form><div class="grid"><?php while($s=$rs->fetch_assoc()): ?><div class="card scholarship"><span class="tag"><?=e($s['education_level']?:'All levels')?></span><span class="tag"><?=e($s['field_of_study']?:'Any field')?></span><h3><?=e($s['title'])?></h3><p><?=e($s['description'])?></p><div class="amount">৳<?=number_format($s['amount'])?></div><div class="meta">Provider: <?=e($s['provider_name'])?><br>Minimum CGPA: <?=e($s['min_cgpa'])?><br>Deadline: <?=e($s['deadline'])?><br>Country: <?=e($s['country'])?></div><br><?php if(user()&&user()['role']==='student'):?><a class="btn" href="apply.php?id=<?=$s['id']?>">Apply Now</a><?php else:?><a class="btn secondary" href="login.php">Login to Apply</a><?php endif;?></div><?php endwhile; if($rs->num_rows===0):?><div class="panel"><p>No matching scholarships found.</p></div><?php endif;?></div></div></body></html>